-- pixelrp: the shop stops selling furni the client cannot draw.
--
-- A catalog row sends its furniture's sprite id, and the client looks that id
-- up in FurnitureData.json to find the furni's name, bundle and icon. A sprite
-- that is not in there has none of them: the tile is a blank square, and it
-- could not be placed in a room either. 119's A-Z catch-all (Misc > More
-- Furni) shelved every uncatalogued furniture row, and a great many of those
-- point at sprites FurnitureData has never had - Misc > P was mostly blanks.
-- check-catalog-icons.py --prune describes the same rows; it needs the VPS,
-- this does not.
--
-- The ids below are every furnitype in beta's FurnitureData.json on
-- 2026-09-26 (26374 floor, 836 wall), our own gamedata-merge lines included. Only
-- furniture of type 's' or 'i' is judged - bots, effects, badges and pets are
-- sold through other types and are not in that file - and deals are left
-- alone. Rows go from every page, not only Misc: an undrawable furni is blank
-- wherever it is shelved.
--
-- The FURNITURE rows are not touched, and neither is anybody's inventory.
-- Afterwards, pages under Misc left with nothing on them are deleted, as 180
-- did.
--
-- Runs once (the deploy records it). Anything added to FurnitureData later is
-- unaffected by it.

DROP TABLE IF EXISTS `_fd_ids`;
CREATE TABLE `_fd_ids` (
    `type` VARCHAR(2) NOT NULL, `sprite_id` INT NOT NULL,
    PRIMARY KEY (`type`, `sprite_id`)) ENGINE=InnoDB;

DELETE ci FROM `catalog_items` ci
  JOIN `furniture` f ON CAST(f.`id` AS CHAR) = ci.`item_id`
  LEFT JOIN `_fd_ids` d ON d.`type` = f.`type` AND d.`sprite_id` = f.`sprite_id`
 WHERE f.`type` IN ('s', 'i')
   AND f.`interaction_type` NOT IN ('deal', 'roomdeal')
   AND d.`sprite_id` IS NULL;

DROP TABLE `_fd_ids`;

-- Pages under Misc left empty, letters first and then More Furni.
SET @furni := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = -1 AND `page_link` = 'furni' LIMIT 1);
SET @misc := (SELECT `id` FROM `catalog_pages` WHERE `parent_id` = @furni AND `caption` = 'Misc' LIMIT 1);

DROP TABLE IF EXISTS `_misc_pages`;
CREATE TABLE `_misc_pages` (`id` INT NOT NULL PRIMARY KEY) ENGINE=InnoDB;
    SELECT c.`id` FROM `catalog_pages` c JOIN `_misc_pages` p ON c.`parent_id` = p.`id`;
    SELECT c.`id` FROM `catalog_pages` c JOIN `_misc_pages` p ON c.`parent_id` = p.`id`;

DELETE p FROM `catalog_pages` p
  JOIN `_misc_pages` m ON m.`id` = p.`id`
 WHERE NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);
DELETE p FROM `catalog_pages` p
  JOIN `_misc_pages` m ON m.`id` = p.`id`
 WHERE NOT EXISTS (SELECT 1 FROM `catalog_items` ci WHERE ci.`page_id` = p.`id`)
   AND NOT EXISTS (SELECT 1 FROM (SELECT `parent_id` FROM `catalog_pages`) c WHERE c.`parent_id` = p.`id`);

DROP TABLE `_misc_pages`;
